<?php namespace App\Http\Controllers; use App\Models\{Applicant,Document,PpdbSetting,StatusHistory}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class AdminController extends Controller { public function login(){return view('admin.login');} public function authenticate(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt($c)){$r->session()->regenerate();return redirect()->route('admin.dashboard');}return back()->withErrors(['email'=>'Kredensial tidak sesuai.']);} public function logout(Request $r){Auth::logout();$r->session()->invalidate();return redirect()->route('admin.login');} public function dashboard(){$counts=Applicant::selectRaw('status,count(*) total')->groupBy('status')->pluck('total','status');return view('admin.dashboard',compact('counts'));} public function applicants(Request $r){$q=Applicant::query();if($r->search)$q->where(fn($x)=>$x->where('full_name','like','%'.$r->search.'%')->orWhere('nisn','like','%'.$r->search.'%')->orWhere('registration_number','like','%'.$r->search.'%'));if($r->status)$q->where('status',$r->status);return view('admin.applicants',['applicants'=>$q->latest()->paginate(10)->withQueryString()]);} public function show(Applicant $applicant){$applicant->load('parent','documents','histories');return view('admin.show',compact('applicant'));} public function status(Request $r,Applicant $applicant){$r->validate(['status'=>'required','notes'=>'nullable']);$applicant->update(['status'=>$r->status]);$applicant->histories()->create(['status'=>$r->status,'notes'=>$r->notes,'changed_by'=>auth()->id()]);return back()->with('ok','Status diperbarui.');} public function document(Request $r,Document $document){$r->validate(['status'=>'required','notes'=>'required_if:status,Ditolak']);$document->update($r->only('status','notes'));return back()->with('ok','Dokumen diperbarui.');} public function settings(){return view('admin.settings',['setting'=>PpdbSetting::firstOrFail()]);} public function saveSettings(Request $r){$d=$r->validate(['academic_year'=>'required','registration_start'=>'required|date','registration_end'=>'required|date','quota'=>'required|integer','fee'=>'required','status'=>'required','description'=>'nullable']);PpdbSetting::firstOrFail()->update($d);return back()->with('ok','Pengaturan disimpan.');}}
